BEGIN;

WITH rdi_filtrado AS (
    SELECT
        rdi.*,
        ROW_NUMBER() OVER (
            PARTITION BY rdi.id_rota, rdi.id_discente
            ORDER BY rdi.data_cadastro DESC 
        ) AS rn
    FROM transporte.rota_discente rdi
    WHERE rdi.ativo = trueValue()
)
	SELECT
   'UPDATE transporte.rota_discente SET ativo = FALSE WHERE id_rota_discente IN ( ' || string_agg(rdi.id_rota_discente::text,',') || ');' solucao,
   'UPDATE transporte.rota_discente SET ativo = TRUE WHERE id_rota_discente IN ( ' || string_agg(rdi.id_rota_discente::text,',') || ');' backup
FROM rdi_filtrado rdi
JOIN transporte.rota r
    USING (id_rota)
JOIN transporte.rota_detalhe rd
    USING (id_rota)
JOIN transporte.rota_veiculo rv
    USING (id_rota)
JOIN discente d
    USING (id_discente)
JOIN comum.pessoa p
    USING (id_pessoa)
LEFT JOIN transporte.veiculo v
    USING (id_veiculo)
JOIN ensino.turno t
    USING (id_turno)
JOIN basico.matricula_estudante_serie mes
    ON mes.id_estudante = d.id_discente
   AND mes.id_situacao_matricula_serie = 1
JOIN basico.turma_serie ts
    USING (id_turma_serie)
JOIN escola.escola e
    ON e.id_escola = rd.id_escola
   AND e.id_escola = ts.id_escola
JOIN comum.unidade u
    ON u.id_unidade = e.id_regional_ensino
JOIN comum.municipio m
    ON m.id_municipio = COALESCE(e.id_municipio, u.id_municipio)
LEFT JOIN comum.registro_entrada re
    ON re.id_entrada = rdi.id_registro_cadastro
LEFT JOIN comum.usuario us
    ON us.id_usuario = re.id_usuario
LEFT JOIN comum.pessoa pe
    ON pe.id_pessoa = us.id_pessoa
WHERE
    rdi.rn = 1  
    AND rdi.data_cadastro IS NOT NULL 
    AND mes.ano_calendario =2026 -- mantém apenas o mais recente
    AND r.ativo 
    AND rv.ativo;


